def search_contacts(account_id, query, is_business=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # accept trailing Z
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_key(v, default_min=True):
        dt = _parse_dt(v) if isinstance(v, str) else None
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if default_min else datetime.datetime.max.replace(
                tzinfo=datetime.timezone.utc
            )
        return dt

    def _is_ulidish(s):
        return isinstance(s, str) and bool(re.fullmatch(r"[0-9A-HJKMNP-TV-Z]{26}", s))

    def _valid_prefixed_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        if not s.startswith(prefix):
            return False
        return _is_ulidish(s[len(prefix) :])

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- usage log / quota / rate limit ----
    def _log(endpoint, status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if isinstance(quota, int) and quota > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    endpoint = "search_contacts"
    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _log(endpoint, "error", meta={"error": lim_err["error"]})
        return lim_err

    # ---- validate ----
    if not _valid_prefixed_ulid(account_id, "wa_acct_"):
        e = _err("VALIDATION_ERROR", "account_id must be a wa_acct_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if not isinstance(query, str) or not query.strip():
        e = _err("VALIDATION_ERROR", "query must be a non-empty string")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if is_business is not None and not isinstance(is_business, bool):
        e = _err("VALIDATION_ERROR", "is_business must be boolean when provided")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    allowed_sort = {
        "last_interaction_at_desc",
        "last_interaction_at_asc",
        "display_name_asc",
        "display_name_desc",
        "created_at_desc",
        "created_at_asc",
    }
    if sort is None:
        sort = "last_interaction_at_desc"
    if sort not in allowed_sort:
        e = _err("VALIDATION_ERROR", "sort is invalid", allowed=sorted(list(allowed_sort)))
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    cur = None
    if cursor is not None:
        cur = _decode_cursor(cursor)
        if not cur or cur.get("account_id") != account_id or cur.get("endpoint") != endpoint:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        e = _err("NOT_FOUND", "Account not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    contacts = _load("contacts.json")
    rows = [c for c in contacts if c.get("account_id") == account_id]

    q = query.strip().lower()

    def _field_str(v):
        return "" if v is None else str(v)

    def _rank(c):
        # Higher score means better match
        score = 0
        for field in ("display_name", "push_name", "phone_e164", "contact_jid"):
            val = _field_str(c.get(field)).lower()
            if not val:
                continue
            if val == q:
                score += 100
            elif val.startswith(q):
                score += 50
            elif q in val:
                score += 10
        return score

    # Filter by query and is_business
    filtered = []
    for c in rows:
        if is_business is not None and c.get("is_business") is not is_business:
            continue
        if _rank(c) <= 0:
            continue
        filtered.append(c)

    # Sort
    def _sort_key(c):
        if sort.startswith("last_interaction_at_"):
            dt = _dt_key(c.get("last_interaction_at"), default_min=True)
            # tie-breakers: display_name, created_at, id
            return (dt, _field_str(c.get("display_name")).lower(), _dt_key(c.get("created_at"), default_min=True), c.get("id"))
        if sort.startswith("display_name_"):
            name = _field_str(c.get("display_name")).lower()
            return (name, _dt_key(c.get("last_interaction_at"), default_min=True), c.get("id"))
        if sort.startswith("created_at_"):
            dt = _dt_key(c.get("created_at"), default_min=True)
            return (dt, _dt_key(c.get("last_interaction_at"), default_min=True), c.get("id"))
        return (c.get("id"),)

    reverse = sort.endswith("_desc")
    # For missing datetimes we used min; for desc this pushes missing to end? Actually min with reverse=True => end. Good.
    filtered.sort(key=_sort_key, reverse=reverse)

    # Apply cursor as offset into this ordered list
    start = 0
    if cur:
        try:
            start = int(cur.get("offset", 0))
            if start < 0:
                raise ValueError()
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    page = filtered[start : start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = _encode_cursor({"endpoint": endpoint, "account_id": account_id, "offset": next_offset}) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "query": query,
        "account_id": account_id,
        "limit": limit,
        "sort": sort,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log(endpoint, "ok", meta={"returned": len(page), "total": len(filtered)})
    return resp

def list_messages(account_id, chat_id, direction=None, type=None, delivery_status=None, before=None, after=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
