            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_ulidish(s):
        return isinstance(s, str) and bool(re.fullmatch(r"[0-9A-HJKMNP-TV-Z]{26}", s))

    def _valid_prefixed_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        if not s.startswith(prefix):
            return False
        return _is_ulidish(s[len(prefix) :])

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # ---- usage log / quota / rate limit ----
    def _log(endpoint, status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if isinstance(quota, int) and quota > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    endpoint = "list_messages"
    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _log(endpoint, "error", meta={"error": lim_err["error"]})
        return lim_err

    # ---- validate ----
    if not _valid_prefixed_ulid(account_id, "wa_acct_"):
        e = _err("VALIDATION_ERROR", "account_id must be a wa_acct_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if not _valid_prefixed_ulid(chat_id, "wa_chat_"):
        e = _err("VALIDATION_ERROR", "chat_id must be a wa_chat_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    if direction is not None and direction not in ("inbound", "outbound"):
        e = _err("VALIDATION_ERROR", "direction is invalid", allowed=["inbound", "outbound"])
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    allowed_types = ("text", "image", "video", "audio", "document", "sticker", "location", "contact", "reaction", "system")
    if type is not None and type not in allowed_types:
        e = _err("VALIDATION_ERROR", "type is invalid", allowed=list(allowed_types))
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    allowed_ds = ("received", "queued", "sent", "delivered", "read", "failed")
    if delivery_status is not None and delivery_status not in allowed_ds:
        e = _err("VALIDATION_ERROR", "delivery_status is invalid", allowed=list(allowed_ds))
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    dt_before = None
    dt_after = None
    if before is not None:
        dt_before = _parse_dt(before)
        if dt_before is None:
            e = _err("VALIDATION_ERROR", "before must be an RFC3339 date-time string")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e
    if after is not None:
        dt_after = _parse_dt(after)
        if dt_after is None:
            e = _err("VALIDATION_ERROR", "after must be an RFC3339 date-time string")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e
    if dt_before and dt_after and not (dt_after < dt_before):
        e = _err("VALIDATION_ERROR", "after must be strictly before before")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    if sort is None:
        sort = "timestamp_desc"
    if sort not in ("timestamp_desc", "timestamp_asc"):
        e = _err("VALIDATION_ERROR", "sort is invalid", allowed=["timestamp_desc", "timestamp_asc"])
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    cur = None
    if cursor is not None:
        cur = _decode_cursor(cursor)
        if not cur or cur.get("endpoint") != endpoint or cur.get("account_id") != account_id or cur.get("chat_id") != chat_id:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        e = _err("NOT_FOUND", "Account not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    chats = _load("chats.json")
    chat = next((c for c in chats if c.get("id") == chat_id and c.get("account_id") == account_id), None)
    if not chat or chat.get("status") == "deleted":
        e = _err("NOT_FOUND", "Chat not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    messages = _load("messages.json")
    rows = [m for m in messages if m.get("account_id") == account_id and m.get("chat_id") == chat_id]

    # Exclude deleted-for-me by default (no override param provided)
    rows = [m for m in rows if not m.get("is_deleted_for_me", False)]

    if direction is not None:
        rows = [m for m in rows if m.get("direction") == direction]
    if type is not None:
        rows = [m for m in rows if m.get("type") == type]
    if delivery_status is not None:
        rows = [m for m in rows if m.get("delivery_status") == delivery_status]

    def _msg_ts(m):
        dt = _parse_dt(m.get("timestamp"))
        if dt is None:
            # schema says not null; treat missing as very old
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dt

    if dt_before is not None:
        rows = [m for m in rows if _msg_ts(m) < dt_before]
    if dt_after is not None:
        rows = [m for m in rows if _msg_ts(m) > dt_after]

    reverse = sort == "timestamp_desc"
    # Tie-breaker prefers recent timestamp ties -> updated_at desc then id
    def _tie_dt(m, field):
        dt = _parse_dt(m.get(field))
        if dt is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return dt

    rows.sort(
        key=lambda m: (_msg_ts(m), _tie_dt(m, "updated_at"), m.get("id")),
        reverse=reverse,
    )

    start = 0
    if cur:
        try:
            start = int(cur.get("offset", 0))
            if start < 0:
                raise ValueError()
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    page = rows[start : start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _encode_cursor({"endpoint": endpoint, "account_id": account_id, "chat_id": chat_id, "offset": next_offset}) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "account_id": account_id,
        "chat_id": chat_id,
        "limit": limit,
        "sort": sort,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log(endpoint, "ok", meta={"returned": len(page), "total": len(rows)})
    return resp

