                if ts and ts >= cutoff:
                    c += 1
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    endpoint = "list_chats"
    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _log(endpoint, "error", meta={"error": lim_err["error"]})
        return lim_err

    # ---- validate ----
    if not _valid_prefixed_ulid(account_id, "wa_acct_"):
        e = _err("VALIDATION_ERROR", "account_id must be a wa_acct_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    if type is not None and type not in ("direct", "group"):
        e = _err("VALIDATION_ERROR", "type is invalid", allowed=["direct", "group"])
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if status is not None and status not in ("active", "hidden", "deleted"):
        e = _err("VALIDATION_ERROR", "status is invalid", allowed=["active", "hidden", "deleted"])
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if is_archived is not None and not isinstance(is_archived, bool):
        e = _err("VALIDATION_ERROR", "is_archived must be boolean when provided")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if is_muted is not None and not isinstance(is_muted, bool):
        e = _err("VALIDATION_ERROR", "is_muted must be boolean when provided")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if has_unread is not None and not isinstance(has_unread, bool):
        e = _err("VALIDATION_ERROR", "has_unread must be boolean when provided")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    dt_updated_after = None
    if updated_after is not None:
        dt_updated_after = _parse_dt(updated_after)
        if dt_updated_after is None:
            e = _err("VALIDATION_ERROR", "updated_after must be an RFC3339 date-time string")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        e = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    allowed_sort = {
        "last_message_at_desc",
        "last_message_at_asc",
        "updated_at_desc",
        "updated_at_asc",
        "created_at_desc",
        "created_at_asc",
    }
    if sort is None:
        sort = "last_message_at_desc"
    if sort not in allowed_sort:
        e = _err("VALIDATION_ERROR", "sort is invalid", allowed=sorted(list(allowed_sort)))
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    cur = None
    if cursor is not None:
        cur = _decode_cursor(cursor)
        if not cur or cur.get("endpoint") != endpoint or cur.get("account_id") != account_id:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        e = _err("NOT_FOUND", "Account not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    chats = _load("chats.json")
    rows = [c for c in chats if c.get("account_id") == account_id]

    # list_chats rule: status != deleted always (even if filter asks deleted)
    rows = [c for c in rows if c.get("status") != "deleted"]

    if type is not None:
        rows = [c for c in rows if c.get("type") == type]
    if status is not None:
        # since deleted are excluded already, status='deleted' yields empty set
        rows = [c for c in rows if c.get("status") == status]
    if is_archived is not None:
        rows = [c for c in rows if c.get("is_archived") is is_archived]
    if is_muted is not None:
        rows = [c for c in rows if c.get("is_muted") is is_muted]
    if has_unread is not None:
        if has_unread:
            rows = [c for c in rows if isinstance(c.get("unread_count"), int) and c.get("unread_count") > 0]
        else:
            rows = [c for c in rows if isinstance(c.get("unread_count"), int) and c.get("unread_count") == 0]
    if dt_updated_after is not None:
        rows = [c for c in rows if _dt_key(c.get("updated_at"), default_min=True) > dt_updated_after]

    # unread_count must be >=0; if invalid, treat as validation error on stored data? We'll filter out invalid negatives.
    rows = [c for c in rows if not isinstance(c.get("unread_count"), int) or c.get("unread_count") >= 0]

    # Sort
    if sort.startswith("last_message_at_"):
        # Denormalized sort: last_message_at desc then updated_at desc per business rule
        reverse = sort.endswith("_desc")
        rows.sort(
            key=lambda c: (_dt_key(c.get("last_message_at"), default_min=True), _dt_key(c.get("updated_at"), default_min=True), c.get("id")),
            reverse=reverse,
        )
    elif sort.startswith("updated_at_"):
        reverse = sort.endswith("_desc")
        rows.sort(key=lambda c: (_dt_key(c.get("updated_at"), default_min=True), _dt_key(c.get("last_message_at"), default_min=True), c.get("id")), reverse=reverse)
    elif sort.startswith("created_at_"):
        reverse = sort.endswith("_desc")
        rows.sort(key=lambda c: (_dt_key(c.get("created_at"), default_min=True), _dt_key(c.get("updated_at"), default_min=True), c.get("id")), reverse=reverse)

    start = 0
    if cur:
        try:
            start = int(cur.get("offset", 0))
            if start < 0:
                raise ValueError()
        except Exception:
            e = _err("VALIDATION_ERROR", "cursor is malformed")
            _log(endpoint, "error", meta={"error": e["error"]})
            return e

    page = rows[start : start + limit]
    next_offset = start + len(page)
    has_more = next_offset < len(rows)
    next_cursor = _encode_cursor({"endpoint": endpoint, "account_id": account_id, "offset": next_offset}) if has_more else None

    resp = {
        "object": "list",
        "data": page,
        "account_id": account_id,
        "limit": limit,
        "sort": sort,
        "total": len(rows),
        "has_more": has_more,
        "next_cursor": next_cursor,
    }
    _log(endpoint, "ok", meta={"returned": len(page), "total": len(rows)})
    return resp

def get_chat(account_id, chat_id, **_extra):
    import json, os, datetime, time, re

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _is_ulidish(s):
        return isinstance(s, str) and bool(re.fullmatch(r"[0-9A-HJKMNP-TV-Z]{26}", s))

    def _valid_prefixed_ulid(s, prefix):
        if not isinstance(s, str):
            return False
        if not s.startswith(prefix):
            return False
        return _is_ulidish(s[len(prefix) :])

    # ---- usage log / quota / rate limit ----
    def _log(endpoint, status, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(endpoint):
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        rate = cfg.get("rate_limit_per_minute")
        quota = cfg.get("quota_per_day")
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rate, int) and rate > 0:
            cutoff = now - datetime.timedelta(minutes=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)
        if isinstance(quota, int) and quota > 0:
            cutoff = now - datetime.timedelta(days=1)
            c = 0
            for r in logs:
                if r.get("endpoint") != endpoint:
                    continue
                ts = _parse_dt(r.get("timestamp"))
                if ts and ts >= cutoff:
                    c += 1
            if c >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=quota, window_seconds=86400)
        return None

    endpoint = "get_chat"
    lim_err = _enforce_limits(endpoint)
    if lim_err:
        _log(endpoint, "error", meta={"error": lim_err["error"]})
        return lim_err

    if not _valid_prefixed_ulid(account_id, "wa_acct_"):
        e = _err("VALIDATION_ERROR", "account_id must be a wa_acct_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e
    if not _valid_prefixed_ulid(chat_id, "wa_chat_"):
        e = _err("VALIDATION_ERROR", "chat_id must be a wa_chat_... ULID")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        e = _err("NOT_FOUND", "Account not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    chats = _load("chats.json")
    chat = next((c for c in chats if c.get("id") == chat_id and c.get("account_id") == account_id), None)
    if not chat or chat.get("status") == "deleted":
        e = _err("NOT_FOUND", "Chat not found")
        _log(endpoint, "error", meta={"error": e["error"]})
        return e

    resp = {"object": "chat", "data": chat}
    _log(endpoint, "ok", meta={"chat_id": chat_id})
    return resp

def get_message_context(account_id, message_id, before_limit=None, after_limit=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            if v.tzinfo is None:
                return v.replace(tzinfo=datetime.timezone.utc)
            return v.astimezone(datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return (f"{prefix}{ts:013d}{rnd:020x}")[: len(prefix) + 33]

    def _pick_log_collection():
        try:
            files = set(os.listdir(_DB)) if os.path.isdir(_DB) else set()
        except Exception:
            files = set()
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                return cand
        return None

    def _log(endpoint, status, account_id_used=None, error_code=None, started_at=None):
        log_name = _pick_log_collection()
        if not log_name:
            return
        logs = _load(log_name)
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        row = {
            "id": _gen_id("wa_req_"),
            "endpoint": endpoint,
            "account_id": account_id_used,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        logs.append(row)
        _save(log_name, logs)

    started = time.time()
    endpoint = "get_message_context"

    # Validate inputs (relax: message_id just needs to be a string; do not enforce prefix)
    if not isinstance(account_id, str) or not account_id.strip():
        _log(endpoint, "error", account_id_used=None, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string", account_id=account_id)
    if not isinstance(message_id, str) or not message_id.strip():
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string", account_id=account_id, message_id=message_id)

    if before_limit is None:
        before_limit = 20
    if after_limit is None:
        after_limit = 20
    if not isinstance(before_limit, int) or not isinstance(after_limit, int):
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "before_limit and after_limit must be integers", before_limit=before_limit, after_limit=after_limit)
    if before_limit < 0 or before_limit > 200 or after_limit < 0 or after_limit > 200:
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "before_limit/after_limit must be within 0–200", before_limit=before_limit, after_limit=after_limit)

    # Load data
    accounts = _load("accounts.json")
    contacts = _load("contacts.json")  # not strictly needed, but keep store access realistic
    chats = _load("chats.json")
    messages = _load("messages.json")

    # Normalize containers
    if isinstance(accounts, dict) and "rows" in accounts and isinstance(accounts["rows"], list):
        accounts = accounts["rows"]
    if isinstance(contacts, dict) and "rows" in contacts and isinstance(contacts["rows"], list):
        contacts = contacts["rows"]
    if isinstance(chats, dict) and "rows" in chats and isinstance(chats["rows"], list):
        chats = chats["rows"]
    if isinstance(messages, dict) and "rows" in messages and isinstance(messages["rows"], list):
        messages = messages["rows"]

    if not isinstance(accounts, list) or not isinstance(chats, list) or not isinstance(messages, list):
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "datastore not initialized")

    # Account must exist (do not require connected for reads)
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == account_id:
            acct = a
            break
    if acct is None or acct.get("status") == "deleted":
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "account not found", account_id=account_id)

    # Find target message owned by the account.
    # IMPORTANT: callers may mistakenly pass a non-message id; return NOT_FOUND (not VALIDATION_ERROR).
    target = None
    for m in messages:
        if isinstance(m, dict) and m.get("id") == message_id and m.get("account_id") == account_id:
            target = m
            break
    if target is None:
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "message not found", account_id=account_id, message_id=message_id)

    chat_id = target.get("chat_id")
    if not isinstance(chat_id, str) or not chat_id:
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "message has no chat", account_id=account_id, message_id=message_id)

    # Validate chat exists and is owned by account (FK integrity)
    chat = None
    for c in chats:
        if isinstance(c, dict) and c.get("id") == chat_id and c.get("account_id") == account_id:
            chat = c
            break
    if chat is None or chat.get("status") == "deleted":
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "chat not found", account_id=account_id, chat_id=chat_id)

    # Collect messages in the same chat/account. Exclude soft-deleted "for me" from the window,
    # but always include the target message even if soft-deleted, because context is explicitly requested.
    in_chat = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") != account_id or m.get("chat_id") != chat_id:
            continue
        if m.get("id") != target.get("id") and m.get("is_deleted_for_me") is True:
            continue
        ts = _parse_dt(m.get("timestamp")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        # Secondary tie-breaker: stable order by created_at/updated_at/id when timestamps equal/missing
        created = _parse_dt(m.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        updated = _parse_dt(m.get("updated_at")) or created
        in_chat.append((ts, updated, created, str(m.get("id") or ""), m))

    # Sort ascending (oldest->newest) for windowing
    in_chat.sort(key=lambda x: (x[0], x[1], x[2], x[3]))

    # Find index of target by id
    target_idx = None
    for i, (_, _, _, _, m) in enumerate(in_chat):
        if m.get("id") == target.get("id"):
            target_idx = i
            break

    # If target was excluded due to malformed row, re-insert it and retry.
    if target_idx is None:
        ts = _parse_dt(target.get("timestamp")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        created = _parse_dt(target.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        updated = _parse_dt(target.get("updated_at")) or created
        in_chat.append((ts, updated, created, str(target.get("id") or ""), target))
        in_chat.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        for i, (_, _, _, _, m) in enumerate(in_chat):
            if m.get("id") == target.get("id"):
                target_idx = i
                break

    if target_idx is None:
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "message not found in chat context", account_id=account_id, message_id=message_id, chat_id=chat_id)

    start = max(0, target_idx - before_limit)
    end = min(len(in_chat), target_idx + 1 + after_limit)

    before_msgs = [in_chat[i][4] for i in range(start, target_idx)]
    after_msgs = [in_chat[i][4] for i in range(target_idx + 1, end)]

    # Optionally include quoted message if present and not already in window (and not soft-deleted),
    # but only if it exists within same account+chat (quoted_remote_message_id is per-chat unique key).
    quoted = None
    quoted_remote_id = target.get("quoted_remote_message_id")
    if isinstance(quoted_remote_id, str) and quoted_remote_id.strip():
        for m in messages:
            if not isinstance(m, dict):
                continue
            if m.get("account_id") != account_id or m.get("chat_id") != chat_id:
                continue
            if m.get("remote_message_id") == quoted_remote_id:
                if m.get("is_deleted_for_me") is True and m.get("id") != target.get("id"):
                    quoted = None
                else:
                    quoted = m
                break

        if quoted is not None:
            existing_ids = set()
            for x in before_msgs:
                if isinstance(x, dict) and x.get("id"):
                    existing_ids.add(x["id"])
            if isinstance(target, dict) and target.get("id"):
                existing_ids.add(target["id"])
            for x in after_msgs:
                if isinstance(x, dict) and x.get("id"):
                    existing_ids.add(x["id"])
            if quoted.get("id") not in existing_ids:
                # attach separately; do not disturb the main chronological window
                pass
            else:
                quoted = None

    resp = {
        "account_id": account_id,
        "chat": chat,
        "target": target,
        "before": before_msgs,
        "after": after_msgs,
        "quoted": quoted,
        "meta": {
            "before_limit": before_limit,
            "after_limit": after_limit,
            "returned_before": len(before_msgs),
            "returned_after": len(after_msgs),
            "total_in_chat_considered": len(in_chat),
        },
    }

    _log(endpoint, "ok", account_id_used=account_id, error_code=None, started_at=started)
    return resp

def send_message(account_id, chat_id, type, text=None, media=None, quoted_remote_message_id=None, client_reference_id=None, **_extra):
    import json, os, datetime, time, random, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
            # json.load can raise; that's fine to bubble? contract: must not raise; handle parse errors
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _is_ulidish(s):
        if not isinstance(s, str) or "_" not in s:
            return False
        p, r = s.split("_", 1)
        return bool(p) and bool(r) and len(r) >= 10

    def _gen_id(prefix):
        # best-effort ULID-like sortable id using ms timestamp + randomness
        t = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        body = f"{t:013d}{rnd:020x}"
        return f"{prefix}_{body}"

    def _log(endpoint, status, account_id_used=None, extra=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        row = {
            "id": f"req_{int(now*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id_used,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    started = time.time()
    endpoint = "send_message"

    # Validate inputs
    if not _is_ulidish(account_id) or not str(account_id).startswith("wa_acct_"):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "account_id must be a wa_acct_… ULID-like string.")
    if not _is_ulidish(chat_id) or not str(chat_id).startswith("wa_chat_"):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "chat_id must be a wa_chat_… ULID-like string.")
    allowed_types = {"text", "image", "video", "audio", "document", "sticker", "location", "contact"}
    if type not in allowed_types:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "Unsupported message type.", allowed=list(sorted(allowed_types)))

    if text is not None and not isinstance(text, str):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "text must be a string when provided.")
    if media is not None and not isinstance(media, dict):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "media must be an object when provided.")
    if quoted_remote_message_id is not None and not isinstance(quoted_remote_message_id, str):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "quoted_remote_message_id must be a string when provided.")
    if client_reference_id is not None and not isinstance(client_reference_id, str):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "client_reference_id must be a string when provided.")

    # Required content per type
    if type == "text":
        if not isinstance(text, str) or text.strip() == "":
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "text is required for type='text'.")
    elif type in {"image", "video", "audio", "document", "sticker"}:
        if media is None or not isinstance(media, dict) or len(media) == 0:
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", f"media is required for type='{type}'.")
        # caption allowed in text (optional)
    elif type in {"location", "contact"}:
        # backend-specific object required in media for these too (normalized payload)
        if media is None or not isinstance(media, dict) or len(media) == 0:
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", f"media is required for type='{type}' (payload object).")

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Account not found.")

    chats = _load("chats.json")
    chat = next((c for c in chats if isinstance(c, dict) and c.get("id") == chat_id and c.get("account_id") == account_id and c.get("status") != "deleted"), None)
    if not chat:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Chat not found for this account.")

    jobs = _load("outbound_message_jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    messages = _load("messages.json")
    if not isinstance(messages, list):
        messages = []

    # Idempotency: client_reference_id dedupe for same account
    if client_reference_id:
        for j in jobs:
            if not isinstance(j, dict):
                continue
            payload = j.get("payload")
            if j.get("account_id") == account_id and isinstance(payload, dict) and payload.get("client_reference_id") == client_reference_id:
                # Return existing job + associated message if present
                sent_mid = j.get("sent_message_id")
                msg = None
                if sent_mid:
                    msg = next((m for m in messages if isinstance(m, dict) and m.get("id") == sent_mid), None)
                resp = {"job": j, "message": msg}
                _log(endpoint, "ok", account_id_used=account_id, extra={"idempotent": True, "job_id": j.get("id")}, started_at=started)
                return resp

    now_iso = _now_iso()
    # Create message row (outbound, queued). remote_message_id unknown at enqueue; create a local placeholder.
    # Ensure uniqueness constraint (account_id, chat_id, remote_message_id): use deterministic unique value.
    remote_message_id = f"local:{client_reference_id}" if client_reference_id else f"local:{_gen_id('tmp')}"
    # If by chance exists, make another
    existing = next((m for m in messages if isinstance(m, dict) and m.get("account_id") == account_id and m.get("chat_id") == chat_id and m.get("remote_message_id") == remote_message_id), None)
    if existing:
        remote_message_id = f"{remote_message_id}:{_gen_id('n')}"
    msg_id = _gen_id("wa_msg")
    msg_row = {
        "id": msg_id,
        "account_id": account_id,
        "chat_id": chat_id,
        "remote_message_id": remote_message_id,
        "from_jid": acct.get("wa_user_jid") or "unknown@s.whatsapp.net",
        "to_jid": chat.get("chat_jid"),
        "direction": "outbound",
        "type": type,
        "text": text if isinstance(text, str) else None,
        "media": media if isinstance(media, dict) else None,
        "quoted_remote_message_id": quoted_remote_message_id if isinstance(quoted_remote_message_id, str) else None,
        "timestamp": now_iso,
        "delivery_status": "queued",
        "failure_reason": None,
        "is_deleted_for_me": False,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Create job
    job_id = _gen_id("wa_job")
    payload = {
        "type": type,
        "text": text if isinstance(text, str) else None,
        "media": media if isinstance(media, dict) else None,
        "quoted_remote_message_id": quoted_remote_message_id if isinstance(quoted_remote_message_id, str) else None,
    }
    if client_reference_id:
        payload["client_reference_id"] = client_reference_id

    job_row = {
        "id": job_id,
        "account_id": account_id,
        "chat_id": chat_id,
        "payload": payload,
        "status": "queued",
        "attempt_count": 0,
        "max_attempts": 3,
        "last_error": None,
        "sent_message_id": msg_id,
        "requested_at": now_iso,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Business rule: only accept when account connected; otherwise reject or mark failed immediately.
    if acct.get("status") != "connected":
        job_row["status"] = "failed"
        job_row["last_error"] = "Account not connected."
        job_row["updated_at"] = now_iso
        msg_row["delivery_status"] = "failed"
        msg_row["failure_reason"] = "Account not connected."
        msg_row["updated_at"] = now_iso

    # Persist
    messages.append(msg_row)
    jobs.append(job_row)

    # Update chat denorm fields best-effort
    chat_changed = False
    for c in chats:
        if isinstance(c, dict) and c.get("id") == chat_id:
            c["last_message_id"] = msg_id
            c["last_message_at"] = now_iso
            c["updated_at"] = now_iso
            # outbound does not affect unread_count
            chat_changed = True
            break

    _save("messages.json", messages)
    _save("outbound_message_jobs.json", jobs)
    if chat_changed:
        _save("chats.json", chats)

    resp = {"job": job_row, "message": msg_row}
    _log(endpoint, "ok", account_id_used=account_id, extra={"job_id": job_id, "message_id": msg_id, "job_status": job_row["status"]}, started_at=started)
    return resp

def search_messages(account_id, query, chat_id=None, direction=None, type=None, delivery_status=None, before=None, after=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _is_ulidish(s):
        if not isinstance(s, str) or "_" not in s:
            return False
        p, r = s.split("_", 1)
        return bool(p) and bool(r) and len(r) >= 10

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        try:
            s = v.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, account_id_used=None, extra=None, started_at=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        row = {
            "id": f"req_{int(now*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "account_id": account_id_used,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _encode_cursor(ts_iso, mid, direction_sort):
        raw = json.dumps({"t": ts_iso, "id": mid, "s": direction_sort}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "t" not in obj or "id" not in obj or "s" not in obj:
                return None
            return obj
        except Exception:
            return None

    started = time.time()
    endpoint = "search_messages"

    # Validate
    if not _is_ulidish(account_id) or not str(account_id).startswith("wa_acct_"):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "account_id must be a wa_acct_… ULID-like string.")
    if not isinstance(query, str) or query.strip() == "":
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if chat_id is not None:
        if not isinstance(chat_id, str) or not _is_ulidish(chat_id) or not chat_id.startswith("wa_chat_"):
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "chat_id must be a wa_chat_… ULID-like string when provided.")
    if direction is not None and direction not in {"inbound", "outbound"}:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "direction must be 'inbound' or 'outbound' when provided.")
    allowed_types = {"text", "image", "video", "audio", "document", "sticker", "location", "contact", "reaction", "system"}
    if type is not None and type not in allowed_types:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "Invalid type filter.")
    allowed_ds = {"received", "queued", "sent", "delivered", "read", "failed"}
    if delivery_status is not None and delivery_status not in allowed_ds:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "Invalid delivery_status filter.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if sort is None:
        sort = "timestamp_desc"
    if sort not in {"timestamp_desc", "timestamp_asc"}:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "sort must be 'timestamp_desc' or 'timestamp_asc'.")

    before_dt = _parse_dt(before) if before is not None else None
    after_dt = _parse_dt(after) if after is not None else None
    if before is not None and before_dt is None:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "before must be an ISO date-time string.")
    if after is not None and after_dt is None:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "after must be an ISO date-time string.")

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id and a.get("status") != "deleted"), None)
    if not acct:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "NOT_FOUND"}, started_at=started)
        return _err("NOT_FOUND", "Account not found.")

    # If chat_id provided, validate ownership and not deleted
    if chat_id is not None:
        chats = _load("chats.json")
        chat = next((c for c in chats if isinstance(c, dict) and c.get("id") == chat_id and c.get("account_id") == account_id and c.get("status") != "deleted"), None)
        if not chat:
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "NOT_FOUND"}, started_at=started)
            return _err("NOT_FOUND", "Chat not found for this account.")

    cur_obj = _decode_cursor(cursor) if cursor else None
    if cursor and cur_obj is None:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "cursor is invalid.")
    if cur_obj and cur_obj.get("s") != sort:
        _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
        return _err("VALIDATION_ERROR", "cursor sort mismatch.")

    q = query.strip().lower()
    msgs = _load("messages.json")
    if not isinstance(msgs, list):
        msgs = []

    scored = []
    for m in msgs:
        if not isinstance(m, dict):
            continue
        if m.get("account_id") != account_id:
            continue
        if m.get("is_deleted_for_me") is True:
            continue
        if chat_id is not None and m.get("chat_id") != chat_id:
            continue
        if direction is not None and m.get("direction") != direction:
            continue
        if type is not None and m.get("type") != type:
            continue
        if delivery_status is not None and m.get("delivery_status") != delivery_status:
            continue

        ts = _parse_dt(m.get("timestamp"))
        if ts is None:
            continue
        if before_dt is not None and not (ts < before_dt):
            continue
        if after_dt is not None and not (ts > after_dt):
            continue

        # Match primarily against text; also allow match on media filename/mimetype if present
        text_val = m.get("text")
        hay = ""
        if isinstance(text_val, str):
            hay += text_val.lower()
        media_obj = m.get("media")
        if isinstance(media_obj, dict):
            fn = media_obj.get("filename")
            mt = media_obj.get("mimetype")
            if isinstance(fn, str):
                hay += " " + fn.lower()
            if isinstance(mt, str):
                hay += " " + mt.lower()

        if q not in hay:
            continue

        # Basic scoring: position + prefer recent on ties (handled by sorting)
        pos = hay.find(q) if hay else 10**9
        scored.append((ts, m.get("id") or "", pos, m))

    # Sort by timestamp, with preference for recent in desc; tie-breaker by id; and by match position
    if sort == "timestamp_desc":
        scored.sort(key=lambda x: (-x[0].timestamp(), x[2], x[1]))
    else:
        scored.sort(key=lambda x: (x[0].timestamp(), x[2], x[1]))

    # Apply cursor as exclusive start
    if cur_obj:
        cts = _parse_dt(cur_obj.get("t"))
        cid = cur_obj.get("id")
        if cts is None or not isinstance(cid, str):
            _log(endpoint, "error", account_id_used=account_id, extra={"code": "VALIDATION_ERROR"}, started_at=started)
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        filtered = []
        if sort == "timestamp_desc":
            for ts, mid, pos, m in scored:
                if ts < cts or (ts == cts and mid < cid):
                    filtered.append((ts, mid, pos, m))
        else:
            for ts, mid, pos, m in scored:
                if ts > cts or (ts == cts and mid > cid):
                    filtered.append((ts, mid, pos, m))
        scored = filtered

    page = scored[:limit]
    items = [x[3] for x in page]
    has_more = len(scored) > limit
    next_cursor = None
    if has_more and page:
        last_ts = page[-1][0]
        last_id = page[-1][1]
        next_cursor = _encode_cursor(last_ts.isoformat(), last_id, sort)

    resp = {
        "data": items,
        "meta": {
            "limit": limit,
            "sort": sort,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "returned": len(items),
        },
    }
    _log(endpoint, "ok", account_id_used=account_id, extra={"returned": len(items), "has_more": has_more}, started_at=started)
    return resp

