def create_account(display_name=None, phone_e164=None, wa_user_jid=None, idempotency_key=None, **_extra):
    import json, os, datetime, time, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid_like(prefix):
        # deterministic-ish length: prefix already includes trailing underscore
        ts = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ts:013d}{rnd:020x}"[: len(prefix) + 33]

    def _norm_e164(p):
        if p is None:
            return None
        if not isinstance(p, str):
            return None
        s = p.strip()
        if not s:
            return None
        if not s.startswith("+"):
            return None
        digits = s[1:]
        if not digits.isdigit():
            return None
        if not (8 <= len(digits) <= 15):
            return None
        return "+" + digits

    def _norm_jid(j):
        if j is None:
            return None
        if not isinstance(j, str):
            return None
        s = j.strip()
        if not s:
            return None
        m = re.match(r"^(\d+)@([a-z0-9.\-]+)$", s)
        if not m:
            return None
        user, host = m.group(1), m.group(2)
        if host not in ("s.whatsapp.net", "c.us"):
            return None
        return f"{user}@{host}"

    def _log(endpoint, status, account_id_used=None, error_code=None, started_at=None):
        try:
            files = os.listdir(_DB) if os.path.isdir(_DB) else []
        except Exception:
            files = []
        log_name = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                log_name = cand
                break
        if not log_name:
            return
        logs = _load(log_name)
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        logs.append(
            {
                "id": _gen_ulid_like("wa_req_"),
                "endpoint": endpoint,
                "account_id": account_id_used,
                "status": status,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save(log_name, logs)

    started = time.time()
    endpoint = "create_account"

    if display_name is not None and not isinstance(display_name, str):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if phone_e164 is not None and not isinstance(phone_e164, str):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "phone_e164 must be a string")
    if wa_user_jid is not None and not isinstance(wa_user_jid, str):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "wa_user_jid must be a string")
    if idempotency_key is not None and not isinstance(idempotency_key, str):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "idempotency_key must be a string")

    ne164 = _norm_e164(phone_e164)
    if phone_e164 is not None and ne164 is None:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "phone_e164 must be a valid E.164 number like +14155552671")
    njid = _norm_jid(wa_user_jid)
    if wa_user_jid is not None and njid is None:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "wa_user_jid must look like 14155552671@s.whatsapp.net")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "accounts store is corrupted")

    # Idempotency: accept returning existing account by idempotency_key if it matches an existing account id,
    # or if an existing account stores the key (future compatible).
    if idempotency_key:
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("id") == idempotency_key or a.get("idempotency_key") == idempotency_key:
                if a.get("status") != "deleted":
                    _log(endpoint, "ok", account_id_used=a.get("id"), started_at=started)
                    return {"account": a, "idempotent": True}
                # if deleted, treat as not found for idempotency and allow recreation with same key

    # Conflict checks: only against non-deleted accounts (business rule)
    # DO NOT reject if the only match is deleted.
    if ne164 is not None:
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("status") == "deleted":
                continue
            if a.get("phone_e164") == ne164:
                _log(endpoint, "error", account_id_used=a.get("id"), error_code="CONFLICT", started_at=started)
                return _err(
                    "CONFLICT",
                    "Cannot create account: phone_e164 already used by an existing non-deleted account (unique(phone_e164) where phone_e164 is not null).",
                    account_id=a.get("id"),
                    phone_e164=ne164,
                )
    if njid is not None:
        for a in accounts:
            if not isinstance(a, dict):
                continue
            if a.get("status") == "deleted":
                continue
            if a.get("wa_user_jid") == njid:
                _log(endpoint, "error", account_id_used=a.get("id"), error_code="CONFLICT", started_at=started)
                return _err(
                    "CONFLICT",
                    "Cannot create account: wa_user_jid already used by an existing non-deleted account (unique(wa_user_jid) where wa_user_jid is not null).",
                    account_id=a.get("id"),
                    wa_user_jid=njid,
                )

    now = _now_iso()
    new_id = _gen_ulid_like("wa_acct_")
    row = {
        "id": new_id,
        "display_name": display_name,
        "phone_e164": ne164,
        "wa_user_jid": njid,
        "status": "provisioning",
        "session_blob": None,
        "last_seen_at": None,
        "sync_cursor": None,
        "created_at": now,
        "updated_at": now,
    }
    if idempotency_key:
        row["idempotency_key"] = idempotency_key

    accounts.append(row)
    _save("accounts.json", accounts)

    _log(endpoint, "ok", account_id_used=new_id, started_at=started)
    return {"account": row}

def update_account(account_id, display_name=None, status=None, clear_session=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_ulid_like(prefix):
        ts = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ts:013d}{rnd:020x}"[: len(prefix) + 33]

    def _log(endpoint, status_s, account_id_used=None, error_code=None, started_at=None):
        try:
            files = os.listdir(_DB) if os.path.isdir(_DB) else []
        except Exception:
            files = []
        log_name = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                log_name = cand
                break
        if not log_name:
            return
        logs = _load(log_name)
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        logs.append(
            {
                "id": _gen_ulid_like("wa_req_"),
                "endpoint": endpoint,
                "account_id": account_id_used,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save(log_name, logs)

    started = time.time()
    endpoint = "update_account"

    if not isinstance(account_id, str) or account_id.strip() == "":
        _log(endpoint, "error", account_id_used=None, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")
    if display_name is not None and not isinstance(display_name, str):
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if clear_session is not None and not isinstance(clear_session, bool):
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "clear_session must be a boolean")
    if status is not None:
        if not isinstance(status, str):
            _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("disconnected", "deleted"):
            _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "status must be one of: disconnected, deleted")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "accounts store is corrupted")

    idx = None
    acct = None
    for i, a in enumerate(accounts):
        if isinstance(a, dict) and a.get("id") == account_id:
            idx = i
            acct = a
            break
    if acct is None:
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "account not found", account_id=account_id)

    if acct.get("status") == "deleted":
        _log(endpoint, "error", account_id_used=account_id, error_code="INVALID_TRANSITION", started_at=started)
        return _err("INVALID_TRANSITION", "cannot update an account in status='deleted'", account_id=account_id)

    # Apply display_name
    mutated = False
    if display_name is not None and display_name != acct.get("display_name"):
        acct["display_name"] = display_name
        mutated = True

    # Clear session material
    if clear_session is True:
        if acct.get("session_blob") is not None:
            acct["session_blob"] = None
            mutated = True
        # If currently connected, clearing session implies disconnected in many systems; but only if requested explicitly via status.
        # Keep status as-is unless caller requested transition.

    # Lifecycle transitions for account.status (full lifecycle in schema)
    transitions = {
        "provisioning": ["qr_required", "deleted"],
        "qr_required": ["connected", "deleted"],
        "connected": ["disconnected", "banned", "deleted"],
        "disconnected": ["connected", "deleted"],
        "banned": ["deleted"],
        "deleted": [],
    }

    if status is not None:
        cur = acct.get("status")
        # API-controlled statuses are limited to disconnected/deleted but must still respect lifecycle transitions
        if not isinstance(cur, str) or cur not in transitions:
            _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
            return _err("VALIDATION_ERROR", "account has invalid status in store", account_id=account_id, status=cur)
        if status == cur:
            # idempotent
            pass
        else:
            allowed = transitions.get(cur, [])
            if status not in allowed:
                _log(endpoint, "error", account_id_used=account_id, error_code="INVALID_TRANSITION", started_at=started)
                return _err(
                    "INVALID_TRANSITION",
                    f"illegal status transition {cur!r} -> {status!r}",
                    account_id=account_id,
                    from_status=cur,
                    to_status=status,
                )
            acct["status"] = status
            mutated = True
            if status == "deleted":
                # soft-delete semantics: clear session
                acct["session_blob"] = None

    if not mutated:
        # No success without effect for mutations
        _log(endpoint, "error", account_id_used=account_id, error_code="CONFLICT", started_at=started)
        return _err("CONFLICT", "no changes requested")

    acct["updated_at"] = _now_iso()
    accounts[idx] = acct
    _save("accounts.json", accounts)

    _log(endpoint, "ok", account_id_used=account_id, started_at=started)
    return {"account": acct}

def get_account_qr(account_id, **_extra):
    import json, os, datetime, time, random, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0558000" if __import__("os").path.isdir("./environment_mix/0558000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        ts = int(time.time() * 1000)
        rnd = random.getrandbits(80)
        return f"{prefix}{ts:013d}{rnd:020x}"[: len(prefix) + 33]

    def _log(endpoint, status_s, account_id_used=None, error_code=None, started_at=None):
        try:
            files = os.listdir(_DB) if os.path.isdir(_DB) else []
        except Exception:
            files = []
        log_name = None
        for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if cand in files:
                log_name = cand
                break
        if not log_name:
            return
        logs = _load(log_name)
        if not isinstance(logs, list):
            logs = []
        now = time.time()
        latency_ms = None
        if isinstance(started_at, (int, float)):
            latency_ms = int(max(0, (now - started_at) * 1000))
        logs.append(
            {
                "id": _gen_id("wa_req_"),
                "endpoint": endpoint,
                "account_id": account_id_used,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": latency_ms,
                "timestamp": _now_iso(),
            }
        )
        _save(log_name, logs)

    started = time.time()
    endpoint = "get_account_qr"

    if not isinstance(account_id, str) or account_id.strip() == "":
        _log(endpoint, "error", account_id_used=None, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "account_id must be a non-empty string")

    accounts = _load("accounts.json")
    if not isinstance(accounts, list):
        _log(endpoint, "error", account_id_used=account_id, error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "accounts store is corrupted")

    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == account_id), None)
    if not acct:
        _log(endpoint, "error", account_id_used=account_id, error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "account not found", account_id=account_id)

    status = acct.get("status")
    if status in ("deleted", "banned"):
        _log(endpoint, "error", account_id_used=account_id, error_code="UNAUTHORIZED", started_at=started)
        return _err("UNAUTHORIZED", "account not eligible for QR", account_id=account_id, status=status)

    # Relax transition strictness: if not qr_required, still provide a QR payload and, if legal, move to qr_required.
    # Legal transitions: provisioning -> qr_required; others are not legal, so we don't mutate status there.
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    expires_at = (now + datetime.timedelta(seconds=45)).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # Create deterministic-ish QR string per account per time window, so repeated calls within a short time are stable.
    bucket = int(time.time() // 30)
    seed = f"{account_id}:{status}:{bucket}".encode("utf-8")
    token = base64.urlsafe_b64encode(hashlib.sha256(seed).digest()).decode("utf-8").rstrip("=")
    qr = f"waweb-qr:{account_id}:{token}"

    mutated = False
    if status == "provisioning":
        acct["status"] = "qr_required"
        acct["updated_at"] = _now_iso()
        mutated = True

    # If account is already qr_required, just return QR (no mutation).
    # If disconnected/connected, we still return QR payload without changing status (avoids INVALID_TRANSITION).
    if mutated:
        # Persist status change
        for i, a in enumerate(accounts):
            if isinstance(a, dict) and a.get("id") == account_id:
                accounts[i] = acct
                break
        _save("accounts.json", accounts)

    resp = {"account_id": account_id, "status": acct.get("status"), "qr": qr, "expires_at": expires_at}
    _log(endpoint, "ok", account_id_used=account_id, error_code=None, started_at=started)
    return resp
